head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onrowstatuschange]<br/>DataList 모듈에서 Row 의 상태값이 변경되면 발생합니다.",
    "validation" : [
        "DataList 모듈에서 Row 의 상태값이 변경되면 발생합니다.",
        "info 파라미터로 상태값이 변경된 Row 들의 정보를 객체 배열로 전달합니다.",
        "info.rowIndex 파라미터로 필터/정렬이 적용된 상태를 기준으로 값이 변경된 Cell 의 Row 인덱스값을 숫자로 갖습니다.",
        "setCellAllData() 와 같이 필터/정렬이 해제된 상태로 실행되는 메소드에 의해 값이 변경된 경우 원본(Origin) Row 의 인덱스값을 갖습니다.",
        "info.oldRowStatus 파라미터로 변경되기 이전의 Row 상태값을 갖습니다.",
        "info.newRowStstus 파라미터로 변경된 후의 Row 상태값을 갖습니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("onrowstatuschange", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowstatuschange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
        for (var i=0; i<info.length; i++) {        
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].rowIndex : " + info[i].rowIndex);
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].oldRowStatus : " + info[i].oldRowStatus);
            wf_body_bottom.getObj("scwin").setReturnValue("info["+i+"].newRowStatus : " + info[i].newRowStatus);
        }        
    });      

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})             
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})             
        isFilter = true;
    }	
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }
};



scwin.btn_setCellData_onclick = function (e) {
	target1.setCellData(0, 0, "change");
};



scwin.btn_setCellAllData_onclick = function (e) {
	target1.setCellAllData(0, 0, "change");
};
